    """Perform the given arithmetic operation on two numbers."""
    if operation == 'add':
        return num1 + num2
    elif operation == 'sub':
        return num1 - num2
    elif operation == 'mul':
        return num1 * num2
    elif operation == 'div':
        if num2 == 0:
            raise ValueError("Division by zero is not allowed.")
        return num1 / num2
    else:
        raise ValueError("Invalid operation. Please try again.")

def main():
    num1 = float(input("Enter the first number: "))
    operation = get_valid_input("Enter the operation (+, -, *, /): ", ['add', 'sub', 'mul', 'div'])
    num2 = float(input("Enter the second number: "))

    try:
        result = perform_arithmetic(num1, num2, operation)
        print(f"{num1} {operation} {num2} = {result}")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
